  "help.pressureWeight": "ꯕꯤꯜ ꯈꯨꯗꯤꯡꯃꯛꯇꯒꯤ ꯊꯥꯒꯤ ꯑꯣꯏꯕꯥ ꯑꯦꯁ꯭ꯇꯤꯃꯦꯠ: ꯁꯦꯅꯐꯝ ÷ ꯔꯤꯄꯤꯠ ꯏꯟꯇꯔꯚꯜ (ꯈꯨꯗꯝ ꯑꯣꯏꯅꯥ ₹3,000 ꯊꯥ ꯇꯔꯨꯛꯀꯤ ꯑꯣꯏꯅꯥ → ₹1,000/mo)꯫ ꯋꯥꯟ ꯑꯣꯐ ꯕꯤꯂꯁꯤꯡꯅꯥ ꯃꯄꯨꯡ ꯐꯥꯕꯥ ꯁꯦꯅꯐꯝ ꯑꯗꯨ ꯁꯤꯖꯤꯟꯅꯩ꯫ ꯅꯍꯥꯛꯀꯤ ꯁꯦꯚ ꯇꯧꯔꯕꯥ ꯕꯤꯜ ꯈꯛꯇꯃꯛ — ꯀꯔꯤꯒꯨꯝꯕꯥ ꯑꯃꯠꯇꯥ ꯄ꯭ꯔꯤ-ꯐꯤꯜ ꯇꯧꯗꯦ꯫",
  "help.openBalance": "ꯍꯧꯖꯤꯛ ꯑꯦꯛꯇꯤꯕ ꯕꯤꯂꯁꯤꯡꯗꯥ ꯍꯧꯖꯤꯀꯁꯨ ꯂꯩꯔꯤꯕꯥ ꯑꯄꯨꯅꯕꯥ (ꯊꯥꯒꯤ ꯑꯣꯏꯕꯥ ꯄꯣꯠꯂꯨꯃꯒꯥ ꯃꯥꯟꯅꯗꯦ)꯫",
  "help.dueThisMonth": "ꯍꯧꯖꯤꯛ ꯐꯥꯎꯕꯥ ꯃꯄꯨꯡꯐꯥꯅꯥ ꯄꯤꯗꯕꯥ ꯍꯧꯖꯤꯛ ꯂꯩꯔꯤꯕꯥ ꯀꯦꯂꯦꯟꯗꯔ ꯊꯥ ꯑꯁꯤꯗꯥ ꯄꯤꯒꯗꯕꯥ ꯇꯥꯡ ꯂꯩꯕꯥ ꯕꯤꯂꯁꯤꯡ꯫",
  "help.freeAfterDues": "ꯏꯅꯀꯝ ꯃꯥꯏꯅꯤꯡ ꯇꯧꯗꯨꯅꯥ ꯔꯤꯀꯣꯔꯗ ꯇꯧꯔꯕꯥ ꯑꯃꯁꯨꯡ ꯑꯦꯛꯇꯤꯕ ꯕꯤꯂꯁꯤꯡꯗꯒꯤ ꯊꯥꯒꯤ ꯑꯣꯏꯅꯥ ꯄꯤꯕꯥ ꯑꯦꯁ꯭ꯇꯤꯃꯦꯠ ꯇꯧꯔꯕꯥ ꯗ꯭ꯌꯨꯁꯤꯡ꯫",
  "help.dueHeatmap": "ꯃꯊꯪꯒꯤ ꯅꯨꯃꯤꯠ ꯃꯔꯤꯅꯤꯒꯤ ꯃꯅꯨꯡꯗꯥ ꯕꯤꯜ ꯀꯌꯥ ꯄꯤꯒꯗꯕꯥ ꯑꯃꯁꯨꯡ ꯃꯈꯣꯌꯒꯤ ꯑꯄꯨꯅꯕꯥ ꯁꯦꯅꯐꯝ꯫",
  "help.debtTrend": "ꯑꯩꯈꯣꯌꯅꯥ ꯁ꯭ꯅꯦꯄꯁꯣꯠꯁꯤꯡ ꯂꯩꯔꯤꯕꯥ ꯈ꯭ꯕꯥꯏꯗꯒꯤ ꯑꯔꯤꯕꯥ ꯑꯃꯁꯨꯡ ꯈ꯭ꯕꯥꯏꯗꯒꯤ ꯅꯧꯕꯥ ꯊꯥꯒꯤ ꯃꯔꯛꯇꯥ ꯑꯄꯨꯅꯕꯥ ꯑꯣꯄꯟ ꯕꯦꯂꯦꯟꯁꯇꯥ ꯑꯍꯣꯡꯕꯥ ꯂꯥꯀꯄꯥ꯫",
  "help.chitInstallments": "ꯑꯌꯥꯝꯕꯥ ꯑꯆꯧꯕꯥ ꯆꯤꯇꯁꯤꯡꯅꯥ ꯊꯥꯒꯤ ꯑꯣꯏꯅꯥ ꯆꯞ ꯃꯥꯟꯅꯕꯥ ꯁꯦꯌꯔ (ꯚꯦꯜꯌꯨ ÷ ꯊꯥ) ꯁꯤꯖꯤꯟꯅꯩ꯫ ꯀꯥꯡꯂꯨꯞ ꯈꯔꯅꯥ ꯍꯟꯊꯔꯀꯄꯥ ꯏꯟꯁꯇꯣꯂꯃꯦꯟꯇꯁꯤꯡ (ꯍꯥꯏ ꯉꯟꯅꯥ, ꯂꯣ ꯇꯨꯡꯗꯥ) ꯁꯤꯖꯤꯟꯅꯩ꯫ ꯅꯍꯥꯛꯀꯤ ꯒ꯭ꯔꯨꯄꯀꯥ ꯃꯥꯟꯅꯕꯥ ꯃꯈꯜ ꯑꯗꯨ ꯈꯜꯂꯨ꯫",
  "help.chitMonthsPaid": "ꯅꯍꯥꯛꯅꯥ ꯍꯥꯟꯅꯅꯥ ꯄꯤꯈꯤꯕꯥ ꯏꯟꯁꯇꯣꯂꯃꯦꯟꯇ ꯀꯌꯥ꯫ ꯀꯔꯤꯒꯨꯝꯕꯥ ꯅꯍꯥꯛꯅꯥ ꯴꯶ ꯄꯤꯔꯕꯗꯤ ꯍꯧꯖꯤꯛ ꯊꯥ ꯴꯷ꯇꯥ ꯂꯩꯔꯤ꯫ ꯃꯁꯤꯅꯥ ꯄꯤꯒꯗꯕꯥ ꯁꯦꯅꯐꯝ ꯑꯃꯁꯨꯡ ꯊꯥꯒꯤ ꯃꯁꯤꯡ ꯑꯗꯨ ꯂꯦꯄꯊꯣꯀꯏ꯫",
  "help.chitPayoutReceived": "ꯅꯍꯥꯛꯅꯥ ꯆꯤꯠ ꯂꯧꯕꯥ ꯃꯇꯃꯗꯥ ꯐꯪꯈꯤꯕꯥ ꯇꯁꯦꯡꯕꯥ ꯀꯦꯁ (ꯈꯨꯗꯝ ꯑꯣꯏꯅꯥ ₹4,43,000)꯫ ꯑꯩꯈꯣꯌꯅꯥ ꯃꯁꯤꯗꯒꯤ ꯅꯤꯂꯥꯝ ꯂꯥꯎꯕꯒꯤ ꯗꯤꯁꯀꯥꯎꯟꯇ ꯑꯗꯨ ꯋꯥꯔꯛ ꯇꯧꯏ — ꯅꯍꯥꯛꯅꯥ ꯗꯤꯁꯀꯥꯎꯟꯇ ꯑꯗꯨ ꯒꯦꯁ ꯇꯧꯕꯒꯤ ꯃꯊꯧ ꯇꯥꯗꯦ꯫",
  "help.chitForeman": "ꯑꯣꯔꯒꯅꯥꯏꯖꯔ ꯀꯃꯤꯁꯟ, ꯑꯌꯥꯝꯕꯅꯥ ꯆꯤꯠ ꯚꯦꯜꯌꯨꯒꯤ ꯆꯥꯎꯔꯥꯛꯅꯥ ꯵%, ꯅꯍꯥꯛꯅꯥ ꯁꯦꯜ ꯐꯪꯂꯕꯥ ꯃꯇꯃꯗꯥ ꯄꯣꯠꯇꯒꯤ ꯂꯧꯕꯥ꯫",
  "help.chitDiscount": "ꯅꯤꯂꯥꯝ ꯂꯥꯎꯕꯗꯥ ꯅꯍꯥꯛꯅꯥ ꯃꯄꯨꯡ ꯐꯥꯕꯥ ꯆꯤꯠ ꯚꯦꯜꯌꯨꯗꯒꯤ ꯍꯦꯟꯅꯥ ꯌꯥꯝꯃꯤ — ꯃꯁꯤꯒꯤ ꯗꯤꯁꯀꯥꯎꯟꯇ ꯑꯁꯤ ꯑꯇꯣꯞꯄꯥ ꯃꯦꯝꯕꯔꯁꯤꯡꯒꯥ ꯁꯦꯌꯔ ꯇꯧꯏ꯫ ꯃꯄꯨꯡꯐꯥꯕꯥ ꯆꯤꯠꯀꯤ ꯁꯦꯅꯐꯝ ꯑꯗꯨ ꯀꯩꯗꯧꯉꯩꯗꯥ ꯁꯦꯂꯗꯥ ꯐꯪꯗꯦ꯫",
  "help.chitAdvisor": "ꯅꯍꯥꯛꯅꯥ ꯆꯤꯠ ꯂꯧꯕꯥ ꯌꯥꯕꯥ ꯊꯥꯁꯤꯡꯒꯥ ꯆꯥꯡꯗꯝꯅꯩ: ꯑꯦꯁ꯭ꯇꯤꯃꯦꯠ ꯇꯧꯔꯕꯥ ꯗꯤꯁꯀꯥꯎꯟꯇ, ꯐꯣꯔꯃꯦꯅꯒꯤ ꯃꯇꯨꯡꯗꯥ ꯄꯦꯃꯦꯟꯇ, ꯊꯥ ꯑꯗꯨꯗꯥ ꯅꯍꯥꯛꯀꯤ ꯑꯇꯩ ꯕꯤꯂꯁꯤꯡ, ꯑꯃꯁꯨꯡ ꯅꯍꯥꯛꯅꯥ ꯌꯥꯕꯥ ꯌꯥꯕꯥ ꯃꯦꯛꯁ ꯂꯣꯁ ꯑꯃꯥ꯫",
  "help.chitMaxLoss": "ꯑꯩꯈꯣꯌꯅꯥ ꯅꯍꯥꯛꯀꯤ ꯏꯅꯀꯝ, ꯊꯥꯒꯤ ꯑꯣꯏꯕꯥ ꯗ꯭ꯌꯨꯁꯤꯡ, ꯑꯣꯄꯟ ꯗꯦꯕꯠ, ꯑꯣꯚꯔꯗ꯭ꯌꯨ ꯕꯤꯂꯁꯤꯡ, ꯑꯃꯁꯨꯡ ꯁꯦꯚꯤꯡꯁꯤꯡꯗꯒꯤ ꯃꯦꯛꯁ ꯂꯣꯁ ꯑꯃꯥ ꯄꯤꯅꯕꯥ ꯄꯥꯎꯇꯥꯛ ꯄꯤꯔꯤ — ꯐꯤꯛꯁ ꯇꯧꯔꯕꯥ % ꯅꯠꯇꯦ꯫ ꯇꯣꯏꯅꯥ ꯂꯧꯕꯅꯥ ꯑꯌꯥꯝꯕꯅꯥ ꯃꯁꯤꯗꯒꯤ ꯍꯦꯜꯂꯤ; ꯃꯇꯨꯡ ꯇꯥꯔꯀꯄꯥ ꯊꯥꯁꯤꯡꯗꯥ ꯃꯍꯧꯁꯥꯅꯥ ꯃꯃꯜ ꯍꯟꯊꯩ꯫",
  "help.loanExtraTiming": "ꯂꯥꯛꯀꯗꯧꯔꯤꯕꯥ ꯊꯥꯁꯤꯡ ꯎꯠꯂꯤ: ꯑꯇꯣꯞꯄꯥ ꯕꯤꯂꯁꯤꯡ ꯍꯦꯟꯅꯥ ꯂꯥꯏꯅꯥ ꯂꯩꯕꯥ ꯃꯇꯃꯗꯥ ꯃꯔꯝ ꯑꯗꯨꯅꯥ ꯅꯍꯥꯛꯅꯥ ꯂꯣꯟ ꯑꯁꯤꯒꯤ ꯃꯇꯥꯡꯗꯥ ꯑꯍꯦꯅꯕꯥ ꯁꯦꯜ ꯄꯤꯕꯥ ꯌꯥꯒꯅꯤ, ꯑꯃꯁꯨꯡ ꯅꯍꯥꯛꯅꯥ ꯈ꯭ꯕꯥꯏꯗꯒꯤ ꯅꯦꯝꯕꯥ ꯃꯇꯃꯗꯥ ꯂꯦꯞꯄꯥ ꯌꯥꯕꯥ ꯑꯔꯨꯕꯥ ꯊꯥꯁꯤꯡ꯫",
  "help.incomeEntryBasis": "ꯇꯦꯛ-ꯍꯣꯝ ꯑꯁꯤ ꯇꯦꯛꯁꯀꯤ ꯃꯇꯨꯡꯗꯥ ꯅꯍꯥꯛꯀꯤ ꯕꯦꯉ꯭ꯀꯇꯥ ꯂꯦꯟꯗ ꯇꯧꯔꯤꯕꯥ ꯑꯗꯨꯒꯥ ꯃꯥꯟꯅꯩ, () => {\n      const idx = ꯇꯣꯀꯦꯅꯁꯤꯡ.ꯄꯨꯁ(ꯅꯣꯎꯟ) - ꯱;\n      `__T${idx}__` ꯔꯤꯇꯔꯟ ꯇꯧꯕꯥ;\n    }, ꯑꯃꯁꯨꯡ ꯐꯤꯛꯁ ꯗꯤꯗꯛꯁꯅꯁꯤꯡ — ꯄ꯭ꯔꯦꯁꯔ ꯑꯃꯁꯨꯡ ꯐ꯭ꯔꯤ-ꯀꯦꯁ ꯃꯦꯊꯁꯀꯤꯗꯃꯛꯇꯥ ꯈ꯭ꯕꯥꯏꯗꯒꯤ ꯐꯕꯥ꯫ ꯀꯔꯤꯒꯨꯝꯕꯥ ꯅꯍꯥꯛꯅꯥ ꯑꯦꯟꯇꯔ ꯇꯧꯔꯤꯕꯥ ꯅꯝꯕꯔ ꯈꯨꯗꯤꯡꯃꯛ ꯄ꯭ꯔꯤ-ꯇꯦꯛꯁ ꯑꯣꯏꯔꯕ���ꯤ ꯒ꯭ꯔꯣꯁ ꯑꯁꯤ ꯀꯥꯟꯅꯕꯥ ꯑꯣꯏꯒꯅꯤ; ꯀꯔꯤꯒꯨꯝꯕꯥ ꯇꯦꯛ-ꯍꯣꯝ ꯏꯅꯀꯝ ꯑꯗꯨ ꯒ꯭ꯔꯣꯁꯇꯒꯤ ꯍꯦꯟꯅꯥ ꯅꯦꯝꯂꯕꯗꯤ ꯐ꯭ꯔꯤ ꯀꯦꯁ ꯑꯁꯤ ꯅꯍꯥꯛꯀꯤ ꯇꯁꯦꯡꯕꯥ ꯕꯦꯉ꯭ꯛ ꯕꯦꯂꯦꯟꯁꯇꯒꯤ ꯍꯦꯟꯅꯥ ꯅꯦꯝꯅꯥ ꯎꯕꯥ ꯌꯥꯏ꯫",
  "help.householdPayerBillTag": "ꯐꯦꯃꯤꯂꯤ ꯃꯣꯗꯀꯤꯗꯃꯛꯇꯥ ꯑꯣꯄꯁꯅꯦꯜ: ꯌꯨꯃꯊꯣꯡꯒꯤ ꯄꯂꯁꯅꯥ ꯁ꯭ꯞꯂꯤꯠ ꯔꯦꯁ꯭ꯄꯣꯟꯁꯤꯕꯤꯂꯤꯇꯤ ꯑꯗꯨ ꯐꯣꯡꯗꯣꯀꯄꯥ ꯉꯝꯅꯕꯥ ꯀꯅꯥꯅꯥ ꯄꯦꯃꯦꯟꯇ ꯇꯧꯕꯒꯦ ꯍꯥꯌꯕꯗꯨ ꯇꯦꯒ ꯇꯧ꯫ ꯑꯄꯨꯅꯕꯥ ꯑꯃꯁꯨꯡ ꯄ꯭ꯔꯦꯁꯔ ꯃꯦꯊꯁ ꯑꯁꯤ ꯑꯃꯒꯥ ꯑꯃꯒꯥ ꯃꯥꯟꯅꯩ꯫",
