  "install.hintIos": "ꯑꯣꯟ () => {\n      const idx = ꯇꯣꯀꯦꯅꯁꯤꯡ.ꯄꯨꯁ(ꯅꯣꯎꯟ) - ꯱;\n      `__T${idx}__` ꯔꯤꯇꯔꯟ ꯇꯧꯕꯥ;\n    } ꯅꯠꯔꯒꯥ () => {\n      const idx = ꯇꯣꯀꯦꯅꯁꯤꯡ.ꯄꯨꯁ(ꯅꯣꯎꯟ) - ꯱;\n      `__T${idx}__` ꯔꯤꯇꯔꯟ ꯇꯧꯕꯥ;\n    }: ꯁꯦꯌꯔ ꯇꯧꯔꯣ, ꯃꯗꯨꯒ��� ꯃꯇꯨꯡꯗꯥ ꯍꯣꯝ ꯁ꯭ꯛꯔꯤꯟꯗꯥ ꯍꯥꯄꯆꯤꯜꯂꯨ꯫ ꯍꯥꯡꯗꯣꯀꯄꯥ () => {\n      const idx = ꯇꯣꯀꯦꯅꯁꯤꯡ.ꯄꯨꯁ(ꯅꯣꯎꯟ) - ꯱;\n      `__T${idx}__` ꯔꯤꯇꯔꯟ ꯇꯧꯕꯥ;\n    } ꯅꯍꯥꯛꯀꯤ ꯍꯣꯝ ꯁ꯭ꯛꯔꯤꯅꯗꯒꯤ ꯂꯧꯕꯥ꯫",
